def main():
 p=ROOT/'resources/study-v3.json';data=json.loads(p.read_text());by={t['id']:t for t in data['terms']}
 for row in ROWS.splitlines():
  id,explanation,example=row.split('|');t=by.get(id)
  if not t:continue
  t['explanation']=explanation;t['example']=example;t['exampleType']='synthetic-teaching'
 for id,en,zh,aliases,definition,explanation,example,source in ADDITIONS:
  if id in by:continue
  t=dict(id=id,en=en,zh=zh,aliases=aliases,definition=definition,explanation=explanation,example=example,exampleType='synthetic-teaching',sources=[source]);data['terms'].append(t);by[id]=t
 for t in data['terms']:
  names=[t['zh']]+t['zh'].split('／')
  t['aliases']=list(dict.fromkeys([*t.get('aliases',[]),*names]))
  # The source-linked definition remains valid even when no extra example has been reviewed.
  if not t.get('explanation'):t['explanation']=t['definition']
 data['version']='2026-09-28.4';p.write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n')
 print('Terminology entries:',len(data['terms']),'with examples:',sum(bool(t.get('example')) for t in data['terms']))
if __name__=='__main__':main()
